  const [form, setForm] = useState({ category: "administrative", projectId: "", vendorId: "", beneficiary: "", payrollType: "company_employee", employeeId: "", payrollName: "", description: "", amount: "", taxRate: "0", cashAccountId: "", costItemId: "", fixedAssetId: "", debitAccountId: "", settlementType: "direct", purchaseInvoiceId: "", allocationRatio: "100", date: new Date().toISOString().slice(0, 10) });
